from collections import Counter

def transform(grid):
    H = len(grid); W = len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    act = [[c != bg for c in row] for row in grid]
    rows_with = [i for i in range(H) if any(act[i])]
    out = [row[:] for row in grid]
    if not rows_with:
        return out
    bands = []
    start = prev = rows_with[0]
    for r in rows_with[1:]:
        if r != prev + 1:
            bands.append((start, prev)); start = r
        prev = r
    bands.append((start, prev))
    if len(bands) != 2:
        return out
    (a0, a1), (b0, b1) = bands
    if (a1 - a0) != (b1 - b0):
        return out
    h = a1 - a0 + 1
    # find d maximizing: A active at (i,c) and B active at (i+dy, c+d)  (B = A shifted right d)
    best_d, best_sc = 0, -1
    for d in range(-W, W + 1):
        sc = 0
        for i in range(h):
            for c in range(W):
                if act[a0 + i][c] and 0 <= c + d < W and act[b0 + i][c + d]:
                    sc += 1
        if sc > best_sc:
            best_sc, best_d = sc, d
    if best_d == 0 or best_sc == 0:
        return out
    if best_d > 0:
        # copy = B; B(i,c) corresponds to A(i, c-d)
        for i in range(h):
            for c in range(W):
                s = c - best_d
                if 0 <= s < W and not act[b0 + i][c] and act[a0 + i][s]:
                    out[b0 + i][c] = 1
    else:
        d = -best_d
        # copy = A; A(i,c) corresponds to B(i+dy, c-d)
        for i in range(h):
            for c in range(W):
                s = c - d
                if 0 <= s < W and not act[a0 + i][c] and act[b0 + i][s]:
                    out[a0 + i][c] = 1
    return out
